use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeKeyVO;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeKeyOptions;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeTitleVO;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeDescriptionVO;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeRequiredVO;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeActivationDateVO;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeVersionVO;
use Civi\Lughauth\Features\Access\ConsentPurpose\Application\Usecase\Create\ConsentPurposeCreateResult;
use PHPUnit\Framework\TestCase;

final class ConsentPurposeCreateResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new ConsentPurposeCreateResult();
        $tenantOneValue = new TenantRef('one');
        $tenantOtherValue = new TenantRef('other');
        $copy = $value->tenant($tenantOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TenantRef('one'), $value->getTenant());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenant());
        $this->assertEquals(new TenantRef('one'), $value->getTenantOrCurrent(ConsentPurposeTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenantOrCurrent(ConsentPurposeTenantVO::from($tenantOtherValue))->value());
        $value->unsetTenant();
        $this->assertEquals(new TenantRef('other'), $value->getTenantOrCurrent(ConsentPurposeTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('one'), $value->getTenantOrCurrent(ConsentPurposeTenantVO::from($tenantOtherValue))->value());
        $keyOneValue = ConsentPurposeKeyOptions::MARKETING;
        $keyOtherValue = ConsentPurposeKeyOptions::ANALYTICS;
        $copy = $value->key($keyOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(ConsentPurposeKeyOptions::MARKETING, $value->getKey());
        $this->assertNotEquals(ConsentPurposeKeyOptions::ANALYTICS, $value->getKey());
        $this->assertEquals(ConsentPurposeKeyOptions::MARKETING, $value->getKeyOrCurrent(ConsentPurposeKeyVO::from($keyOtherValue))->value());
        $this->assertNotEquals(ConsentPurposeKeyOptions::ANALYTICS, $value->getKeyOrCurrent(ConsentPurposeKeyVO::from($keyOtherValue))->value());
        $value->unsetKey();
        $this->assertEquals(ConsentPurposeKeyOptions::ANALYTICS, $value->getKeyOrCurrent(ConsentPurposeKeyVO::from($keyOtherValue))->value());
        $this->assertNotEquals(ConsentPurposeKeyOptions::MARKETING, $value->getKeyOrCurrent(ConsentPurposeKeyVO::from($keyOtherValue))->value());
        $titleOneValue = 'one';
        $titleOtherValue = 'other';
        $copy = $value->title($titleOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getTitle());
        $this->assertNotEquals('other', $value->getTitle());
        $this->assertEquals('one', $value->getTitleOrCurrent(ConsentPurposeTitleVO::from($titleOtherValue))->value());
        $this->assertNotEquals('other', $value->getTitleOrCurrent(ConsentPurposeTitleVO::from($titleOtherValue))->value());
        $value->unsetTitle();
        $this->assertEquals('other', $value->getTitleOrCurrent(ConsentPurposeTitleVO::from($titleOtherValue))->value());
        $this->assertNotEquals('one', $value->getTitleOrCurrent(ConsentPurposeTitleVO::from($titleOtherValue))->value());
        $descriptionOneValue = 'one';
        $descriptionOtherValue = 'other';
        $copy = $value->description($descriptionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getDescription());
        $this->assertNotEquals('other', $value->getDescription());
        $this->assertEquals('one', $value->getDescriptionOrCurrent(ConsentPurposeDescriptionVO::from($descriptionOtherValue))->value());
        $this->assertNotEquals('other', $value->getDescriptionOrCurrent(ConsentPurposeDescriptionVO::from($descriptionOtherValue))->value());
        $value->unsetDescription();
        $this->assertEquals('other', $value->getDescriptionOrCurrent(ConsentPurposeDescriptionVO::from($descriptionOtherValue))->value());
        $this->assertNotEquals('one', $value->getDescriptionOrCurrent(ConsentPurposeDescriptionVO::from($descriptionOtherValue))->value());
        $requiredOneValue = true;
        $requiredOtherValue = false;
        $copy = $value->required($requiredOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isRequired());
        $this->assertNotEquals(false, $value->isRequired());
        $this->assertEquals(true, $value->getRequiredOrCurrent(ConsentPurposeRequiredVO::from($requiredOtherValue))->value());
        $this->assertNotEquals(false, $value->getRequiredOrCurrent(ConsentPurposeRequiredVO::from($requiredOtherValue))->value());
        $value->unsetRequired();
        $this->assertEquals(false, $value->getRequiredOrCurrent(ConsentPurposeRequiredVO::from($requiredOtherValue))->value());
        $this->assertNotEquals(true, $value->getRequiredOrCurrent(ConsentPurposeRequiredVO::from($requiredOtherValue))->value());
        $activationDateOneValue = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $activationDateOtherValue = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $copy = $value->activationDate($activationDateOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getActivationDate());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getActivationDate());
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getActivationDateOrCurrent(ConsentPurposeActivationDateVO::from($activationDateOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getActivationDateOrCurrent(ConsentPurposeActivationDateVO::from($activationDateOtherValue))->value());
        $value->unsetActivationDate();
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getActivationDateOrCurrent(ConsentPurposeActivationDateVO::from($activationDateOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getActivationDateOrCurrent(ConsentPurposeActivationDateVO::from($activationDateOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(ConsentPurposeVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(ConsentPurposeVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(ConsentPurposeVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(ConsentPurposeVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
